  <div className="dashboard-grid"><Panel title="Site performance" subtitle="Operational signals across active trial-site associations" action={<button className="text-btn" onClick={() => app.nav('sites')}>All sites <Icon name="arrow" size={15}/></button>}><Table heads={['Site / Study', 'Enrollment', 'Overdue', 'Operational index']} footer={<><span>{m.uniqueSites} unique sites · {m.activeAssociations} active associations</span><span>Rule-based demo index</span></>}>{sites.slice(0, 5).map(ts => { const r = risk(s, ts); return <tr key={ts.id}><td><RecordLink onClick={() => app.open('trialSite', ts.id)}>{s.sites[ts.siteId].city}</RecordLink><small className="cell-sub">{ts.trialId}</small></td><td><span className="tabular">{r.enrollment}<span className="muted"> / {ts.target ?? '—'}</span></span><Progress n={r.enrollment} d={ts.target || 0}/></td><td><span className={r.lateVisits ? 'text-amber' : ''}>{r.lateVisits} visits</span><small className="cell-sub">{r.lateQueries} queries</small></td><td><button className="badge-button" onClick={() => app.open('trialSite', ts.id)}><Badge>{r.band} · {r.score?.toFixed(0) ?? '—'}</Badge></button></td></tr>; })}</Table></Panel>
   <Panel title="On the horizon" subtitle="Evidence and oversight deadlines"><div className="deadline-list">{upcoming.slice(0, 3).map(c => <button className="deadline" key={c.id} onClick={() => app.open('compliance', c.id)}><div className={'date-tile ' + (overdue(c, s.clock) ? 'late' : '')}><b>{new Date(c.due).getUTCDate()}</b><span>{new Intl.DateTimeFormat('en', { month: 'short', timeZone: 'UTC' }).format(new Date(c.due))}</span></div><div><strong>{c.title}</strong><small>{c.trialId} · {c.kind}</small>{overdue(c, s.clock) && <span className="text-amber">Overdue</span>}</div><Icon name="right" size={15}/></button>)}</div><div className="health-strip"><button onClick={() => app.nav('safety', 'Open reviews')}><Icon name="shield" size={18}/><div><strong>{m.safetyReviews} open safety reviews</strong><small>{m.serious} serious / {m.ae} total AE episodes</small></div><Icon name="right" size={15}/></button><button onClick={() => app.nav('compliance', 'Overdue')}><Icon name="file" size={18}/><div><strong>{m.complianceOverdue} overdue compliance items</strong><small>Checklist tracking, not certification</small></div><Icon name="right" size={15}/></button></div></Panel></div>
