    function Toolbar({ app, placeholder = 'Search records…', statuses = [], extra }: any) { return <div className="list-toolbar"><div className="local-search"><Icon name="search" size={17}/><input aria-label="Search this list" placeholder={placeholder} value={app.state.query} onChange={(e: any) => app.set({ query: e.target.value, limit: 20 })}/></div><div className="toolbar-controls">{statuses.length > 0 && <select aria-label="Status filter" value={app.state.status} onChange={(e: any) => app.set({ status: e.target.value, limit: 20 })}>{['All', ...statuses].map((v: string) => <option key={v} value={v}>{v === 'All' ? 'All statuses' : v}</option>)}</select>}<select aria-label="Sort records" value={app.state.sort} onChange={(e: any) => app.set({ sort: e.target.value })}><option value="default">Default order</option><option value="asc">Code / title A–Z</option><option value="desc">Code / title Z–A</option></select>{extra}</div></div>; }
    function sorted<T>(rows: T[], app: App, label: (r: T) => string): T[] { return app.state.sort === 'default' ? rows : [...rows].sort((a, b) => (app.state.sort === 'desc' ? -1 : 1) * label(a).localeCompare(label(b))); }
